definition.script:
// Case Converter

var inputText = input.get("text");
var targetCase = input.get("targetCase") || "camelCase";

if (!inputText) {
    log.error("Text input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Text input is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        // Split input into words
        function toWords(str) {
            // Handle various input formats
            return str
                // Insert space before uppercase letters (for camelCase/PascalCase)
                .replace(/([a-z])([A-Z])/g, '$1 $2')
                // Replace underscores, hyphens, dots with spaces
                .replace(/[_\-\.]+/g, ' ')
                // Replace multiple spaces with single space
                .replace(/\s+/g, ' ')
                // Trim and split
                .trim()
                .toLowerCase()
                .split(' ')
                .filter(function(w) { return w.length > 0; });
        }

        function capitalize(word) {
            return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
        }

        var words = toWords(inputText);
        var result = "";

        switch (targetCase) {
            case "camelCase":
                result = words.map(function(w, i) {
                    return i === 0 ? w.toLowerCase() : capitalize(w);
                }).join('');
                break;

            case "PascalCase":
                result = words.map(function(w) {
                    return capitalize(w);
                }).join('');
                break;

            case "snake_case":
                result = words.map(function(w) {
                    return w.toLowerCase();
                }).join('_');
                break;

            case "SCREAMING_SNAKE_CASE":
            case "CONSTANT_CASE":
                result = words.map(function(w) {
                    return w.toUpperCase();
                }).join('_');
                break;

            case "kebab-case":
                result = words.map(function(w) {
                    return w.toLowerCase();
                }).join('-');
                break;

            case "SCREAMING-KEBAB-CASE":
                result = words.map(function(w) {
                    return w.toUpperCase();
                }).join('-');
                break;

            case "dot.case":
                result = words.map(function(w) {
                    return w.toLowerCase();
                }).join('.');
                break;

            case "Title Case":
                result = words.map(function(w) {
                    return capitalize(w);
                }).join(' ');
                break;

            case "Sentence case":
                result = words.map(function(w, i) {
                    return i === 0 ? capitalize(w) : w.toLowerCase();
                }).join(' ');
                break;

            case "lowercase":
                result = words.join(' ').toLowerCase();
                break;

            case "UPPERCASE":
                result = words.join(' ').toUpperCase();
                break;

            default:
                result = inputText;
        }

        output.set("Result", result);
        output.set("OriginalCase", detectCase(inputText));
        output.set("TargetCase", targetCase);
        output.set("WordCount", words.length);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");

        log.info("Converted to " + targetCase + ": " + result);
        tags.trigger("success");

    } catch (ex) {
        log.error("Conversion failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}

function detectCase(str) {
    if (str.indexOf('_') >= 0 && str === str.toUpperCase()) return "CONSTANT_CASE";
    if (str.indexOf('_') >= 0) return "snake_case";
    if (str.indexOf('-') >= 0 && str === str.toUpperCase()) return "SCREAMING-KEBAB-CASE";
    if (str.indexOf('-') >= 0) return "kebab-case";
    if (str.indexOf('.') >= 0) return "dot.case";
    if (str === str.toUpperCase()) return "UPPERCASE";
    if (str === str.toLowerCase()) return "lowercase";
    if (str.charAt(0) === str.charAt(0).toUpperCase() && str.indexOf(' ') === -1) return "PascalCase";
    if (str.charAt(0) === str.charAt(0).toLowerCase() && str.indexOf(' ') === -1) return "camelCase";
    if (str.indexOf(' ') >= 0) return "Title Case";
    return "unknown";
}
